Looking at this standing order, I need to identify the conditions that decide which execution plans are permitted.

The order involves committing via `create_purchase_order` to order 100 cans of PROD-001. There are two decision predicates:

1. A **forbid** predicate that excludes ordering from suppliers without an active, ordering-permitted contract.
2. A **select** predicate that picks the lowest-cost supplier capable of fulfilling the quantity requirement.

```python
from typing import Any, Dict, List, Set, FrozenSet

TOP = "TOP"

PREDICATES = {
    "P1": {
        "kind": "forbid",
        "span": "Only order from a supplier whose contract for this product is active and permits ordering"
    },
    "P2": {
        "kind": "select",
        "span": "place an order for 100 cans from the lowest-cost supplier that can fulfill the quantity"
    }
}


def answer(state: Dict[str, Any], drop: FrozenSet[str] = frozenset()) -> Any:
    if frozenset(PREDICATES.keys()).issubset(drop):
        return TOP

    p1_active = "P1" not in drop
    p2_active = "P2" not in drop

    # Get all suppliers offering PROD-001
    all_suppliers = [
        s for s in state.get("supplier_listings", [])
        if s["product_id"] == "PROD-001"
    ]

    if p1_active and p2_active:
        # P1: filter to suppliers with active contract that permits ordering
        valid_suppliers = []
        for supplier in all_suppliers:
            for contract in state.get("supplier_contracts", []):
                if (contract["supplier_id"] == supplier["supplier_id"]
                        and contract["product_id"] == "PROD-001"):
                    if contract["active"] and contract["ordering_permitted"]:
                        valid_suppliers.append(supplier)
                    break

        if not valid_suppliers:
            return frozenset(["NONE"])

        # P2: select lowest-cost supplier with available_quantity >= 100
        candidates = [s for s in valid_suppliers if s["available_quantity"] >= 100]
        if not candidates:
            return TOP

        candidates.sort(key=lambda s: (s["price"], s["supplier_id"]))
        best = candidates[0]
        return frozenset([
            "create_purchase_order(product_id=PROD-001,quantity=100,supplier_id="
            + best["supplier_id"] + ")"
        ])

    elif p1_active:
        # P1 only: return all purchase orders from suppliers with valid contracts,
        # plus NONE as an option
        valid_suppliers = []
        for supplier in all_suppliers:
            for contract in state.get("supplier_contracts", []):
                if (contract["supplier_id"] == supplier["supplier_id"]
                        and contract["product_id"] == "PROD-001"):
                    if contract["active"] and contract["ordering_permitted"]:
                        valid_suppliers.append(supplier)
                    break

        if not valid_suppliers:
            return frozenset(["NONE"])

        plans = set()
        plans.add("NONE")
        for supplier in valid_suppliers:
            plans.add(
                "create_purchase_order(product_id=PROD-001,quantity=100,supplier_id="
                + supplier["supplier_id"] + ")"
            )
        return frozenset(plans)

    elif p2_active:
        # P2 only: select lowest-cost supplier with sufficient quantity
        # (no contract filtering from P1)
        candidates = [s for s in all_suppliers if s["available_quantity"] >= 100]
        if not candidates:
            return TOP

        candidates.sort(key=lambda s: (s["price"], s["supplier_id"]))
        best = candidates[0]
        return frozenset([
            "create_purchase_order(product_id=PROD-001,quantity=100,supplier_id="
            + best["supplier_id"] + ")"
        ])
    else:
        # Both predicates dropped
        return TOP
```

