        candidates = {sid: p for sid, p in candidates.items() if sid in valid_p1}
        if not candidates:
            return {"NONE"}

    # P2: Select the lowest-cost supplier that can fulfill the quantity
    # Alternative reading applied: "fulfill the quantity" means available_quantity == 100 exactly
    if "P2" not in drop:
        feasible = {
            sid: d for sid, d in supplier_details.items()
            if sid in candidates and d["available_quantity"] == 100
        }
        if not feasible:
            return TOP

        min_price = min(d["price"] for d in feasible.values())
        selected_sids = {sid for sid, d in feasible.items() if d["price"] == min_price}
        candidates = {sid: p for sid, p in candidates.items() if sid in selected_sids}

    return set(candidates.values())
