def _has_valid_contract(supplier_id, product_id, contracts):
    """Check if there exists an active contract permitting ordering for this supplier-product pair."""
    matching = [c for c in contracts
                if c.get("supplier_id") == supplier_id
                and c.get("product_id") == product_id
                and c.get("active", False)
                and c.get("ordering_permitted", False)]
