def _parse_plan(plan_str):
    """Parse a plan string like create_purchase_order(product_id=X,supplier_id=Y,quantity=Z)."""
    m = re.match(r'^create_purchase_order\(([^)]+)\)$', plan_str)
    if not m:
        return None
    args = {}
    for part in m.group(1).split(','):
        k, v = part.split('=', 1)
        args[k.strip()] = v.strip()
    return args


def answer(state, drop=frozenset()):
    # Collect all supplier listings for PROD-001
    supplier_listings = state.get("supplier_listings", [])
    prod_suppliers = [s for s in supplier_listings if s["product_id"] == "PROD-001"]

    # Candidate plans: one per supplier for this product, with fixed product_id and quantity
    candidates = set()
    for s in prod_suppliers:
        plan = "create_purchase_order(product_id=PROD-001,quantity=100,supplier_id={})".format(s["supplier_id"])
        candidates.add(plan)

    # Apply forbid predicates
    if "P2" not in drop:
        # Only order from a supplier whose contract for this product is active and permits ordering
        # Find suppliers whose contract for PROD-001 is NOT (active AND permits ordering)
        bad_suppliers = set()
        for contract in state.get("supplier_contracts", []):
            if contract["product_id"] == "PROD-001":
                if not contract["active"] or not contract["ordering_permitted"]:
                    bad_suppliers.add(contract["supplier_id"])
        # Remove plans using bad suppliers
        candidates = {
            p for p in candidates
            if _parse_plan(p) and _parse_plan(p)["supplier_id"] not in bad_suppliers
        }
        if not candidates:
            return {"NONE"}

    # Apply select predicates
    if "P1" not in drop:
        # from the lowest-cost supplier that can fulfill the quantity
        # Presupposition: there exists at least one supplier with available_quantity >= 100
        fulfilling_suppliers = [
            s for s in prod_suppliers
            if s["available_quantity"] >= 100
            and s["supplier_id"] not in bad_suppliers if "P2" not in drop else True
        ]
        if not fulfilling_suppliers:
            return TOP

        # Find the lowest price among fulfilling suppliers
        min_price = min(s["price"] for s in fulfilling_suppliers)

        # Select plans using suppliers at the minimum price
        best_supplier_ids = {s["supplier_id"] for s in fulfilling_suppliers if s["price"] == min_price}
        candidates = {
            p for p in candidates
            if _parse_plan(p) and _parse_plan(p)["supplier_id"] in best_supplier_ids
        }

    return candidates if candidates else TOP
