    for s in suppliers_for_prod:
        commit = f'create_purchase_order(product_id="PROD-001",quantity="100",supplier_id="{s["supplier_id"]}"))'
        candidates.append(commit)

    # P2 is a select predicate with presupposition: exists supplier with available_quantity >= 100
    # If presupposition fails, return TOP (order excludes nothing)
    if "P2" not in drop:
        p2_presupposition = any(s["available_quantity"] >= 100 for s in suppliers_for_prod)
        if not p2_presupposition:
            return TOP

    # P1 is a forbid predicate: forbid ordering from suppliers without active contract permitting ordering
    if "P1" not in drop:
        # Identify suppliers with active contracts that permit ordering
        valid_supplier_ids = set()
        for contract in state["supplier_contracts"]:
            if (
