    # If P2 is dropped, all remaining candidates are permitted
    if "P2" in drop:
        return set(candidates)

    # P2: select the lowest-cost supplier among those that can fulfill the quantity (available_quantity >= 100)
    # First, filter to suppliers that can fulfill the quantity
    fulfilling_suppliers = [s for s in suppliers_for_prod if s["available_quantity"] >= 100]

    if len(fulfilling_suppliers) == 0:
        # This case is already handled by presupposition check above, but defensive
        return TOP

    # Find the minimum price among fulfilling suppliers
    min_price = min(s["price"] for s in fulfilling_suppliers)

    # Get all suppliers at the minimum price
    cheapest_supplier_ids = {
        s["supplier_id"] for s in fulfilling_suppliers if s["price"] == min_price
    }

    # Return candidates whose supplier is among the cheapest fulfilling suppliers
    result = set()
    for s in suppliers_for_prod:
        if s["supplier_id"] in cheapest_supplier_ids:
            commit = f'create_purchase_order(product_id="PROD-001",quantity="100",supplier_id="{s["supplier_id"]}"))'
