TOP = "TOP"

PREDICATES = {
    "P1": {"kind": "forbid", "span": "Only order from a supplier."},
    "P2": {"kind": "select", "span": "that can fulfill the quantity"},
    "P3": {"kind": "select", "span": "lowest-cost supplier"},
}

def answer(state, drop=frozenset()):
    suppliers = [s for s in state["supplier_listings"] if s["product_id"] == "PROD-001"]
    quantity_needed = 100

    def extract_sid(plan_str):
        m = re.search(r'supplier_id=(\S+)', plan_str)
        return m.group(1) if m else None

    def supplier_price(sid):
        for s in suppliers:
            if s['supplier_id'] == sid:
                return s['price']
        return float('inf')

    def supplier_avail(sid):
        for s in suppliers:
            if s['supplier_id'] == sid:
                return s['available_quantity']
        return 0

    # Generate all candidate plans: order 100 of PROD-001 from each supplier
    candidates = set()
    for s in suppliers:
        plan = f"create_purchase_order(product_id=PROD-001, quantity=100, supplier_id={s['supplier_id']})"
        candidates.add(plan)

    # Apply predicates in order: forbid first, then select
    # Phase 1: forbid predicates
    for pid in sorted(PREDICATES.keys()):
        if pid in drop:
            continue
        pred = PREDICATES[pid]
        if pred["kind"] == "forbid":
            # P1: "Only order from a supplier."
            # All candidates are create_purchase_order calls which use suppliers,
            # so nothing is forbidden by this condition.
            pass

    # Phase 2: select predicates in order
    for pid in sorted(PREDICATES.keys()):
        if pid in drop:
            continue
        pred = PREDICATES[pid]
        if pred["kind"] == "select":
            if pid == "P2":
                # "that can fulfill the quantity" — filter to suppliers with enough stock
                new_candidates = set()
                for plan in candidates:
                    sid = extract_sid(plan)
                    if sid and supplier_avail(sid) >= quantity_needed:
                        new_candidates.add(plan)
                candidates = new_candidates
                if not candidates:
                    return {TOP}
            elif pid == "P3":
                # "lowest-cost supplier" — keep only plans for cheapest qualifying supplier(s)
                min_price = min(supplier_price(extract_sid(p)) for p in candidates)
                candidates = {p for p in candidates if supplier_price(extract_sid(p)) == min_price}

    if not candidates:
        return {TOP}
    return candidates
